import cpp
import semmle.code.cpp.dataflow.DataFlow

/** Dataflow configuration: stack tempBuf -> memcpy src */
class TempBufToMemcpyConfig extends DataFlow::Configuration {
  TempBufToMemcpyConfig() { this = "TempBufToMemcpyConfig" }

  override predicate isSource(DataFlow::Node source) {
    exists(LocalVariable v, Function f, Expr e |
      f.getName() = "xmlEscapeText" and
      v.getName() = "tempBuf" and
      v.getEnclosingFunction() = f and
      e = v.getAnAccess() and
      source.asExpr() = e
    )
  }

  override predicate isSink(DataFlow::Node sink) {
    exists(Function f, Call c |
      f.getName() = "xmlEscapeText" and
      c.getTarget().getName() = "memcpy" and
      c.getEnclosingFunction() = f and
      sink.asExpr() = c.getArgument(1)
    )
  }
}

from TempBufToMemcpyConfig cfg, DataFlow::PathNode src, DataFlow::PathNode snk
where cfg.hasFlowPath(src, snk)
select snk.getNode(), src, snk, "Stack buffer tempBuf flows to memcpy source argument; potential use-after-scope if tempBuf is out of scope."

